const { withDangerousMod } = require('expo/config-plugins');
const { mkdir, writeFile } = require('node:fs/promises');
const path = require('node:path');

// Keep Studio's daemon selection aligned with the tested Android build JDK.
module.exports = function withGradleJdk(config) {
  return withDangerousMod(config, [
    'android',
    async (config) => {
      const directory = path.join(config.modRequest.platformProjectRoot, 'gradle');
      await mkdir(directory, { recursive: true });
      await writeFile(
        path.join(directory, 'gradle-daemon-jvm.properties'),
        '# Generated by Trip Painting Expo config plugin. Use an installed JDK 17.\ntoolchainVersion=17\n',
      );
      return config;
    },
  ]);
};
